        match self {
            Source::TesPureCoreData => Row {
                miss: MissPolicy::Unresolves,
                batch: Batch::Keys,
            },
            Source::TesTweet => Row {
                miss: MissPolicy::Unresolves,
                batch: Batch::Unrecorded,
            },
            Source::TesConversationControl => Row {
                miss: MissPolicy::FailsNode,
                batch: Batch::Keys,
            },
