                miss: MissPolicy::FailsNode,
                batch: Batch::Requested,
            },
            Source::GizmoduckViewer => Row {
                miss: MissPolicy::FailsNode,
                batch: Batch::Unrecorded,
            },
            Source::GizmoduckAuthor => Row {
                miss: MissPolicy::Unresolves,
                batch: Batch::Keys,
            },
