                miss: MissPolicy::FailsNode,
                batch: Batch::Keys,
            },
            Source::ViewerCountry => Row {
                miss: MissPolicy::FailsNode,
                batch: Batch::Unrecorded,
            },
            Source::Wingman => Row {
