    pub(super) const fn scope(self) -> Scope {
        match self {
            Source::TesPureCoreData => <exchange::TesPureCoreData as Exchange>::SCOPE,
            Source::TesTweet => <exchange::TesTweet as Exchange>::SCOPE,
